    <script>
        async function runSlash(command) {
            if (window.TavernHelper && typeof window.TavernHelper.triggerSlash === 'function') {
                return await window.TavernHelper.triggerSlash(command);
            }
            if (typeof window.triggerSlash === 'function') {
                return await window.triggerSlash(command);
            }
            throw new Error('当前环境未提供 triggerSlash');
        }

        async function sendQuickReply(message) {
            const text = String(message ?? '').trim();
            if (!text) return;
            const statusSuffix = isCharging ? ' 充电中' : ' 未充电';
            const textWithStatus = text + statusSuffix;
            try {
                // 首先使用 /send 命令将消息添加到历史记录
                const cmd = `/send ${textWithStatus}`;
                await runSlash(cmd);

                // 然后触发AI生成回复
                if (window.TavernHelper && typeof window.TavernHelper.generate === 'function') {
                    // 使用酒馆助手的generate函数直接触发AI生成
                    await window.TavernHelper.generate({ user_input: textWithStatus });
                } else if (typeof window.generate === 'function') {
                    // 备用方案：使用全局generate函数
                    await window.generate({ user_input: textWithStatus });
                } else {
                    // 如果都没有，尝试使用 /generate 命令
                    await runSlash('/generate');
                }
            } catch (err) {
                console.warn('发送快捷回复失败: ', err);
            }
        }

        const appContent = {
