        function getMainImageEl() {
            return document.querySelector('.img-wrapper img');
        }

        function setMainImageImmediate(targetSrc, options = { bounce: false }) {
            const img = getMainImageEl();
            if (!img) return;
            const current = img.getAttribute('src');
            if (current !== targetSrc) {
                img.src = targetSrc;
            }
            if (options.bounce) {
                // 重新触发一次动画
                img.classList.remove('bounce-once');
                // 强制重绘
                void img.offsetWidth;
                img.classList.add('bounce-once');
                const clear = () => { img.classList.remove('bounce-once'); img.removeEventListener('animationend', clear); };
                img.addEventListener('animationend', clear);
            }
        }

        function setMainImageState(state) {
            const target = MAIN_IMAGE_MAP[state];
            if (!target) return;
            setMainImageImmediate(target);
        }

        // 实时北京时间（Asia/Shanghai）
        function startBeijingClock() {
            const el = document.querySelector('.status-bar .time-display');
            if (!el) return;
            const fmt = new Intl.DateTimeFormat('en-US', {
                timeZone: 'Asia/Shanghai',
                hour12: true,
                hour: 'numeric',
                minute: '2-digit'
            });
            function tick() {
                el.textContent = fmt.format(new Date());
                setTimeout(tick, 60000 - (Date.now() % 60000));
            }
            tick();
        }

        // 电量显示：在支持 Battery Status API 的浏览器中启用
        function setupBatteryStatus() {
            // 检查 Battery API 是否支持
            if (!navigator.getBattery) {
                if (isBatteryListenerActive && batteryManager) {
                    // 如果 API 突然变得不支持，且监听器处于激活状态，则清理
                    batteryManager.removeEventListener('levelchange', batteryLevelListenerFn);
                    batteryManager.removeEventListener('chargingchange', batteryChargingListenerFn);
                    isBatteryListenerActive = false;
                    batteryManager = null; // 清除管理器
                    console.log('Battery API unsupported, listeners removed.');
                }
                return; // 不支持 Battery API，无需进行其他操作
            }

            if (chargingControlMode === 'device') {
                // 期望处于设备模式：确保监听器处于激活状态
                if (!isBatteryListenerActive) {
                    // 仅当监听器未激活时，尝试获取电池并添加监听器
                    navigator.getBattery().then((battery) => {
                        batteryManager = battery; // 存储 batteryManager 实例
                        batteryLevelListenerFn = () => applyBatteryStateFromDevice();
                        batteryChargingListenerFn = () => applyBatteryStateFromDevice();

                        batteryManager.addEventListener('levelchange', batteryLevelListenerFn);
                        batteryManager.addEventListener('chargingchange', batteryChargingListenerFn);
                        isBatteryListenerActive = true;
                        console.log('Battery status listeners added.');

                        // 首次应用设备状态
                        applyBatteryStateFromDevice(); // 确保视觉效果立即匹配设备状态

                    }).catch(err => {
                        console.warn('Failed to get battery status, falling back to default/manual.', err);
                        isBatteryListenerActive = false; // 确保失败时标志正确
                        batteryManager = null;
                    });
                } else {
                    // 已经处于设备模式且监听器已激活，只需确保视觉效果同步
                    if (batteryManager) { // 检查 batteryManager 是否有效
                        applyBatteryStateFromDevice();
                    }
                }
            } else { // chargingControlMode === 'manual'
                // 期望处于手动模式：确保监听器被移除
                if (isBatteryListenerActive && batteryManager) {
                    batteryManager.removeEventListener('levelchange', batteryLevelListenerFn);
                    batteryManager.removeEventListener('chargingchange', batteryChargingListenerFn);
                    isBatteryListenerActive = false;
                    console.log('Switched to manual mode, battery status listeners removed.');
                }
                // 在手动模式下，视觉状态由 assistantData.templateChargingState 控制，
                // 这由 window.setCharging(assistantData.templateChargingState === 1); 处理，
                // 该调用来自单选按钮的 change 监听器或 initAfterPreload。
            }
        }

        // 辅助函数：从设备应用电池状态
        function applyBatteryStateFromDevice() {
            if (!batteryManager) return; 

            const percentEl = document.querySelector('.battery-display > span');
            const levelBar = document.querySelector('.battery-icon .battery-level');
            if (!percentEl || !levelBar) return;

            const p = Math.round((batteryManager.level || 0) * 100);
            percentEl.textContent = p + '%';
            levelBar.style.width = p + '%';
            window.setCharging(!!batteryManager.charging);
        }

        // 解析示例模板并映射到对应区域
        // 示例：
        // 助手名|{{char}}
        // data|(心情)|(想法)|(兴趣)|(状态)
        // 头部触摸|(头部触摸反应)
        // 胸部触摸|(胸部触摸反应)
        // 胯部触摸|(胯部触摸反应)
        // 剧情对话|(剧情对话)
        // 正文|(正文内容)
        function applyTemplateFromText(template, context = {}) {
            if (typeof template !== 'string') return;
            // 不再过滤空行；保留原始行，以便多行块能保留空行
            const lines = template.split(/\r?\n/).map(l => l.replace(/\s+$/,'') /* 去除行尾空白，保留行首缩进 */);
            const substitute = (text) => String(text ?? '').replace(/\{\{(\w+)\}\}/g, (_, k) => (k in context ? String(context[k]) : `{{${k}}}`));
            const toHTML = (s) => String(s ?? '').replace(/\r?\n/g, '<br>');
            const findDelimiterIndex = (line) => {
                const i1 = line.indexOf('|');
                const i2 = line.indexOf('｜'); // 全角竖线
                if (i1 === -1) return i2;
                if (i2 === -1) return i1;
                return Math.min(i1, i2);
            };
            const parseTripleList = (text) => {
                if (typeof text !== 'string') return null;
                // 统一全角括号与竖线
                let s = text.replace(/（/g, '(').replace(/）/g, ')').replace(/｜/g, '|');
                s = s.trim();
                // 允许分隔符与括号内外存在空白，并支持跨行内容（括号版本）
                const m = s.match(/^\(\s*([\s\S]*?)\s*\)\s*\|\s*\(\s*([\s\S]*?)\s*\)\s*\|\s*\(\s*([\s\S]*?)\s*\)$/);
                if (m) {
                    return [m[1], m[2], m[3]].map(part => toHTML(substitute(part)));
                }
                // 无括号版本：以 | 分隔三段
                const parts = s.split('|');
                if (parts.length >= 3) {
                    return parts.slice(0, 3).map(part => toHTML(substitute(part.trim())));
                }
                return null;
            };

            let needRefreshAssistant = false;

            // 当前正在采集的多行块
            let currentBlock = null; // { key: string, lines: string[] }
            const isBlockKey = (key) => (
                key.startsWith('正文') ||
                key.startsWith('剧情对话') ||
                key.startsWith('头部触摸') ||
                key.startsWith('胸部触摸') ||
                key.startsWith('胯部触摸') ||
                key.startsWith('手部触摸') ||
                key.startsWith('脚部触摸')
            );
            const flushBlock = () => {
                if (!currentBlock) return;
                const raw = currentBlock.lines.join('\n');
                const html = toHTML(substitute(raw));
                const key = currentBlock.key;
                if (key.startsWith('正文')) {
                    appContent.safariAppWindow.content = html;
                } else if (key.startsWith('剧情对话')) {
                    appContent.messagesAppWindow.content = html;
                } else if (key.startsWith('头部触摸')) {
                    const triples = parseTripleList(raw);
                    if (triples) {
                        appContent.dialogBoxWindow.faceVariants = triples;
                        appContent.dialogBoxWindow.faceIndex = 0;
                        appContent.dialogBoxWindow.face = triples[0];
                    } else {
                        appContent.dialogBoxWindow.face = html;
                    }
                } else if (key.startsWith('胸部触摸')) {
                    const triples = parseTripleList(raw);
                    if (triples) {
                        appContent.dialogBoxWindow.chestVariants = triples;
                        appContent.dialogBoxWindow.chestIndex = 0;
                        appContent.dialogBoxWindow.chest = triples[0];
                    } else {
                        appContent.dialogBoxWindow.chest = html;
                    }
                } else if (key.startsWith('胯部触摸')) {
                    const triples = parseTripleList(raw);
                    if (triples) {
                        appContent.dialogBoxWindow.crotchVariants = triples;
                        appContent.dialogBoxWindow.crotchIndex = 0;
                        appContent.dialogBoxWindow.crotch = triples[0];
                    } else {
                        appContent.dialogBoxWindow.crotch = html;
                    }
                } else if (key.startsWith('手部触摸')) {
                    const triples = parseTripleList(raw);
                    if (triples) {
                        appContent.dialogBoxWindow.handVariants = triples;
                        appContent.dialogBoxWindow.handIndex = 0;
                        appContent.dialogBoxWindow.hand = triples[0];
                    } else {
                        appContent.dialogBoxWindow.hand = html;
                    }
                } else if (key.startsWith('脚部触摸')) {
                    const triples = parseTripleList(raw);
                    if (triples) {
                        appContent.dialogBoxWindow.legVariants = triples;
                        appContent.dialogBoxWindow.legIndex = 0;
                        appContent.dialogBoxWindow.leg = triples[0];
                    } else {
                        appContent.dialogBoxWindow.leg = html;
                    }
                }
                currentBlock = null;
            };

            for (const rawLine of lines) {
                // 识别新的键行：形如 关键字|内容 或 关键字｜内容（全角）
                const delimIndex = findDelimiterIndex(rawLine);
                if (delimIndex !== -1) {
                    const key = rawLine.slice(0, delimIndex).trim();
                    const after = rawLine.slice(delimIndex + 1); // 原样保留分隔后文本

                    // 遇到新键前，先结束上一个块
                    flushBlock();

                if (key.startsWith('助手名')) {
                        const value = substitute(after.trim());
                        if (value !== '') {
                            assistantData.name = value; // 直接使用模板中的名字
                    const nameEl = document.getElementById('assistant-name');
                    if (nameEl) nameEl.textContent = assistantData.name;
                            // 更新对话框标题与配置
                    if (appContent && appContent.dialogBoxWindow) {
                        appContent.dialogBoxWindow.title = assistantData.name;
                    }
                    const dialogTitleEl = document.querySelector('#dialogBoxWindow .app-window-header span:first-child');
                    if (dialogTitleEl) dialogTitleEl.textContent = assistantData.name;
                    needRefreshAssistant = true;
                        }
                    continue;
                }

                // 新增：好感度|100（或任意文本），写入状态栏
                if (key.startsWith('好感度')) {
                        const value = substitute(after.trim());
                        if (value !== '') {
                            assistantData.favorability = value;
                            const favEl = document.getElementById('assistant-favorability');
                            if (favEl) favEl.textContent = '';
                            needRefreshAssistant = true;
                        }
                        continue;
                }

                if (key.startsWith('data')) {
                        // data|(心情)|(想法)|(兴趣)|(状态) 或 data|心情|想法|兴趣|状态
                        const normalized = after.replace(/｜/g, '|').trim();
                        let match = normalized.match(/^\((.*?)\)\|\((.*?)\)\|\((.*?)\)\|\((.*?)\)$/);
                    if (match) {
                        const [, mood, thoughts, interests, status] = match.map(substitute);
                            assistantData.mood = mood;
                            assistantData.thoughts = thoughts;
                            assistantData.interests = interests;
                            assistantData.status = status;
                            needRefreshAssistant = true;
                        } else {
                            const parts = normalized.split('|').map(s => substitute(s.trim()));
                            if (parts.length >= 4) {
                                const [mood, thoughts, interests, status] = parts;
                        assistantData.mood = mood;
                        assistantData.thoughts = thoughts;
                        assistantData.interests = interests;
                        assistantData.status = status;
                        needRefreshAssistant = true;
                            }
                    }
                    continue;
                }

                    // 单行三段触摸：直接解析，无需等待 flush
                    if (key.startsWith('头部触摸') || key.startsWith('胸部触摸') || key.startsWith('胯部触摸') || key.startsWith('手部触摸') || key.startsWith('脚部触摸')) {
                        const triples = parseTripleList(after);
                        if (triples) {
                if (key.startsWith('头部触摸')) {
                                appContent.dialogBoxWindow.faceVariants = triples;
                                appContent.dialogBoxWindow.faceIndex = 0;
                                appContent.dialogBoxWindow.face = triples[0];
                            } else if (key.startsWith('胸部触摸')) {
                                appContent.dialogBoxWindow.chestVariants = triples;
                                appContent.dialogBoxWindow.chestIndex = 0;
                                appContent.dialogBoxWindow.chest = triples[0];
                            } else if (key.startsWith('胯部触摸')) {
                                appContent.dialogBoxWindow.crotchVariants = triples;
                                appContent.dialogBoxWindow.crotchIndex = 0;
                                appContent.dialogBoxWindow.crotch = triples[0];
                            } else if (key.startsWith('手部触摸')) {
                                appContent.dialogBoxWindow.handVariants = triples;
                                appContent.dialogBoxWindow.handIndex = 0;
                                appContent.dialogBoxWindow.hand = triples[0];
                            } else if (key.startsWith('脚部触摸')) {
                                appContent.dialogBoxWindow.legVariants = triples;
                                appContent.dialogBoxWindow.legIndex = 0;
                                appContent.dialogBoxWindow.leg = triples[0];
                            }
                    continue;
                }
                }

                    if (isBlockKey(key)) {
                        // 开启一个新的多行块，并把本行分隔符后的文本作为第一行内容
                        currentBlock = { key, lines: [after] };
                    continue;
                }

                if (key.startsWith('充电状态')) {
                    const value = parseInt(after.trim(), 10);
                    if (!isNaN(value)) {
                        assistantData.templateChargingState = value;
                    }
                    continue;
                }

                    // 未识别的键，忽略
                    continue;
                }

                // 非键行：如果在块内，则视为块的后续内容
                if (currentBlock) {
                    currentBlock.lines.push(rawLine);
                }
            }

            // 文件结束，仍有块未刷新的情况
            flushBlock();

            if (needRefreshAssistant) {
                populateAssistantUI();
            }
        }

        // 暴露到全局，便于外部调用：window.applyTemplateFromText(text, { char: '卡斯塔莉娅' })
