        function populateAssistantUI() {
            const byId = (id) => document.getElementById(id);
            const set = (id, val) => { const el = byId(id); if (el) el.textContent = val; };
            set('assistant-name', assistantData.name);
            set('assistant-mood', assistantData.mood);
            set('assistant-thoughts', assistantData.thoughts);
            set('assistant-interests', assistantData.interests);
            set('assistant-status', assistantData.status);
            // 顶部不再显示好感度
            set('assistant-favorability', '');

            // 解析好感度并渲染进度条（三阶段上限与颜色）+ 无效值兜底
            try {
                const raw = String(assistantData.favorability ?? '').trim();
                const hasDigit = /\d/.test(raw);
                // 支持 "12345/xxx" 或 纯数字 文本
                let current = 0;
                if (hasDigit) {
                    const slashIdx = raw.indexOf('/');
                    if (slashIdx >= 0) {
                        current = parseInt(raw.slice(0, slashIdx).replace(/[^0-9]/g, ''), 10) || 0;
                    } else {
                        current = parseInt(raw.replace(/[^0-9]/g, ''), 10) || 0;
                    }
                } else {
                    current = 100; // 无数字时按默认100处理
                }

                // 顶部不显示数值
                set('assistant-favorability', '');

                const OVERALL_MAX = 150000;
                let stageMax = 500;
                let barColor = '#3b82f6'; // 蓝色
                if (current > 500 && current <= 2000) {
                    stageMax = 2000;
                    barColor = '#f59e0b'; // 黄色
                } else if (current > 2000) {
                    stageMax = OVERALL_MAX;
                    barColor = '#ec4899'; // 粉红色
                }
                const clampedOverall = Math.max(0, Math.min(current, OVERALL_MAX));
                const clampedStage = Math.max(0, Math.min(clampedOverall, stageMax));
                const pct = Math.round((clampedStage / stageMax) * 100);
                const fill = document.getElementById('favorability-fill');
                if (fill) {
                    fill.style.width = pct + '%';
                    fill.style.background = barColor;
                }
                const hint = document.getElementById('favorability-hint');
                if (hint) hint.textContent = `好感度：${clampedStage}/${stageMax}`;
            } catch (_) {
                // 回退到默认文本和默认进度（100/500, 蓝色），顶部不显示
                set('assistant-favorability', '');
                const fill = document.getElementById('favorability-fill');
                if (fill) {
                    fill.style.width = '20%';
                    fill.style.background = '#3b82f6';
                }
                const hint = document.getElementById('favorability-hint');
                if (hint) hint.textContent = '好感度：100/500';
            }
        }

        // 切换充电状态：仅改变右上角电池图标外观，并打上父容器标记，便于未来联动
        window.setCharging = function setCharging(charging) {
            const batteryIcon = document.querySelector('.battery-icon');
            const batteryPercent = document.querySelector('.battery-display span');
            const centerBox = document.querySelector('.center-box');
            const cable = document.querySelector('.charging-cable-img');
            isCharging = !!charging;
            if (batteryIcon) batteryIcon.classList.toggle('charging', !!charging);
            if (batteryPercent) batteryPercent.classList.toggle('charging', !!charging);
            if (centerBox) centerBox.classList.toggle('charging', !!charging);

            if (cable) {
                if (charging) {
                    // 进入充电：移除离场态，触发上移显示
                    cable.classList.remove('leaving');
                    // 强制重绘，确保过渡从初始态开始
                    void cable.offsetWidth;
                    cable.classList.add('show');
                } else {
                    // 退出充电：先下移再淡出
                    cable.classList.add('leaving');
                    cable.classList.remove('show');
                    const onEnd = (e) => {
                        if (e.propertyName !== 'transform' && e.propertyName !== 'opacity') return;
                        cable.classList.remove('leaving');
                        cable.removeEventListener('transitionend', onEnd);
                    };
                    cable.addEventListener('transitionend', onEnd);
                }
            }
            // 切换充电状态时，同步调整当前展示图：充电→害羞，未充电→普通（若当前在对话框中间，则保持不动，待关闭时恢复）
            const dialog = document.getElementById('dialogBoxWindow');
            const dialogActive = dialog && dialog.classList.contains('active');
            if (!dialogActive) {
                setMainImageImmediate(isCharging ? MAIN_IMAGE_MAP.shy : MAIN_IMAGE_MAP.normal);
            }
        }

        // 根据模板参数应用充电状态
        function applyChargingFromTemplate() {
            if (chargingControlMode === 'manual') {
