            }
        }

        // 仅对话框内容区域启用拖拽滚动（手机端/PC均可用）
        function enableDialogContentDrag() {
            const content = document.querySelector('#dialogBoxWindow .app-window-content');
            if (!content) return;

            const getPoint = (e) => (e.touches && e.touches[0]) ? { x: e.touches[0].clientX, y: e.touches[0].clientY } : { x: e.clientX, y: e.clientY };

            let isDown = false;
            let startY = 0;
            let startX = 0;
            let startTop = 0;
            let startLeft = 0;

            const onStart = (e) => {
                isDown = true;
                const p = getPoint(e);
                startY = p.y;
                startX = p.x;
                startTop = content.scrollTop;
                startLeft = content.scrollLeft;
                content.classList.add('dragging-content');
                if (e.cancelable) e.preventDefault();
            };

            const onMove = (e) => {
                if (!isDown) return;
                const p = getPoint(e);
                const dy = p.y - startY;
                const dx = p.x - startX;
                content.scrollTop = startTop - dy;
                content.scrollLeft = startLeft - dx;
                if (e.cancelable) e.preventDefault();
            };

            const onEnd = () => {
                isDown = false;
                content.classList.remove('dragging-content');
            };

            content.addEventListener('mousedown', onStart);
            window.addEventListener('mousemove', onMove);
            window.addEventListener('mouseup', onEnd);
            content.addEventListener('touchstart', onStart, { passive: false });
            content.addEventListener('touchmove', onMove, { passive: false });
            content.addEventListener('touchend', onEnd);
        }

        function openAppWindow(windowId, contentKey = null) {
            const appWindow = document.getElementById(windowId);
            const contentData = appContent[windowId];

            if (!appWindow || !contentData) return;

            // 仅对非助手app窗口设置标题
            if (windowId !== 'assistantAppWindow') {
                appWindow.querySelector('.app-window-header span:first-child').textContent = contentData.title;
            }

            // 仅对非助手app窗口写入内容
            const contentElement = appWindow.querySelector('.app-window-content');
            if (windowId === 'dialogBoxWindow' && contentKey) {
                // 优先顺序触发三段反应
                const keyBase = contentKey; // face | chest | crotch | hand
                const listKey = keyBase + 'Variants';
                const idxKey = keyBase + 'Index';
                const list = contentData[listKey];
                if (Array.isArray(list) && list.length > 0) {
                    const idx = (contentData[idxKey] || 0) % list.length;
                    contentElement.innerHTML = list[idx];
                    contentData[idxKey] = (idx + 1) % list.length;
                } else {
                contentElement.innerHTML = contentData[contentKey];
                }
            } else if (windowId !== 'assistantAppWindow') {
                contentElement.innerHTML = contentData.content;
            }

            if (windowId === 'assistantAppWindow') {
                populateAssistantUI();
            }

            appWindow.classList.add('active');

            // 打开对话框后，10秒自动淡出消失
            if (windowId === 'dialogBoxWindow') {
                if (dialogAutoHideTimer) clearTimeout(dialogAutoHideTimer);
                dialogAutoHideTimer = setTimeout(() => {
                    closeAppWindow('dialogBoxWindow');
                }, 6000);
            }
        }

