                content: '这是浏览器应用的内容。<br>您可以模拟浏览网页。<br><br>...'.repeat(10)
            },
            musicAppWindow: {
                title: '音乐',
                content: '还没想好这里做什么'
            },
            assistantAppWindow: {
                title: '←',
                content: ''
            },
            dialogBoxWindow: {
                title: '对话框',
                face: '这是面部按键触发的对话框内容。<br>您可以添加更多关于面部相关的信息。<br><br>...'.repeat(5),
                chest: '这是胸部按键触发的对话框内容。<br>您可以添加更多关于胸部相关的信息。<br><br>...'.repeat(5),
                crotch: '这是胯部按键触发的对话框内容。<br>您可以添加更多关于胯部相关的信息。<br><br>...'.repeat(5),
                hand: '这是手部触碰触发的对话框内容。<br>你们彼此轻轻握住了手。<br><br>...'.repeat(5),
                leg: '这是脚部触摸触发的对话框内容。<br>她轻轻挪动了一下。<br><br>...'.repeat(5),
                // 五段触摸反应与索引
                faceVariants: [],
                chestVariants: [],
                crotchVariants: [],
                handVariants: [],
                legVariants: [],
