        };

        // 统一参数对象（用于和页面静态结构匹配）
        const assistantData = {
            name: '卡斯塔莉娅',
            favorability: '90344/90500',
            mood: '开心',
            thoughts: '想出去散步',
            interests: '音乐、阅读',
            status: '小憩中',
            templateChargingState: 0 // 新增：从模板中读取的充电状态 (0: 未充电, 1: 充电中)
        };

        // 提前定义模板文本，便于预加载阶段扫描其中可能的图片
        const TEMPLATE_INCOMING = document.getElementById('dynamicTemplateContainer')?.textContent || '';

    //     const TEMPLATE_INCOMING = `
    //     助手名|米露可
    // data|开心|想聊天|音乐|在线
    // 头部触摸|摸摸头|轻抚|揉揉
