    // 正文|请选择你的回应
    // 选项|我很开心|我想聊天|我想听音乐
    // 充电状态|1`;

        // 主体图片资源（将用于主体展示与预加载）
        const MAIN_IMAGE_SOURCES = [
            'https://files.catbox.moe/k134tf.png', // 普通
            'https://files.catbox.moe/lqu1y6.png', // 害羞
            'https://files.catbox.moe/k134tf.png', // 眨眼笑
