            ];

            // 从传入内容格式中提取选项的函数
            function extractOptionsFromContent() {
                // 获取传入的内容格式（这里需要根据实际情况获取）
                // 假设内容格式存储在某个变量中，或者从某个地方获取
                let contentFormat = '';

                // 尝试从不同的地方获取内容格式
                if (window.currentContentFormat) {
                    contentFormat = window.currentContentFormat;
                } else if (typeof TEMPLATE_INCOMING === 'string' && TEMPLATE_INCOMING) {
                    // 使用脚本内的常量 TEMPLATE_INCOMING（不是 window 属性）
                    contentFormat = TEMPLATE_INCOMING;
                } else {
                    // 如果没有找到内容格式，返回默认回复
                    return replies;
                }

                // 解析内容格式，提取选项部分
                const lines = String(contentFormat).split(/\r?\n/);
                let options = [];

                for (const raw of lines) {
                    const line = String(raw ?? '').trim();
                    if (!line) continue;
                    // 允许有空格：如 "选项 | A | B | C"
                    if (!line.includes('|')) continue;
                    const parts = line.split('|').map(s => s.trim());
                    if (parts.length < 4) continue; // 标签 + 至少三项
                    if (parts[0] === '选项') {
                        options = parts.slice(1).filter(Boolean);
                        break;
                    }
                }

                // 如果找到了选项，返回前3个，否则返回默认回复
                return options.length >= 3 ? options.slice(0, 3) : replies;
            }

