            if (text === '助手设置') {
                renderAssistantSettings();
                // 手动模式时，进入设置页也尝试按模板参数应用一次
                try { applyChargingFromTemplate(); } catch (_) {}
            } else if (text === '助手&衣橱' || text === '助手执勤') {
                // 只更新 active 样式，不触发任何内容切换
                // 因为这两个标签页目前没有对应的内容区域需要显示
            } else { // 假设此分支为"助手档案"或其他将来的有效标签
                showAssistantHome();
            }
        });

        // 预加载图片资源并显示进度
        (function setupPreloader(){
            const preloader = document.getElementById('preloader');
            const bar = document.getElementById('preloaderBar');
            const percentText = document.getElementById('preloaderPercent');

            // 提取 <img> src、样式中的 url(...) 以及字符串中的 <img src>
            const extractImgUrlsFromHtmlString = (html) => {
                if (!html) return [];
                const urls = [];
                const re = /<img[^>]+src=["']([^"']+)["']/gi;
                let m;
                while ((m = re.exec(html)) !== null) {
                    urls.push(m[1]);
                }
                return urls;
            };

            const extractUrlsFromStyles = () => {
                const urlRe = /url\(["']?([^\)"']+)["']?\)/gi;
                const urls = [];
                document.querySelectorAll('style').forEach(styleEl => {
                    const text = styleEl.textContent || '';
                    let m;
                    while ((m = urlRe.exec(text)) !== null) {
                        urls.push(m[1]);
                    }
                });
                return urls;
            };

            const collectAllImageUrls = () => {
                const urls = [];
                // 0) 主体图片资源数组
                urls.push(...MAIN_IMAGE_SOURCES);
                // 1) DOM 中已有 <img>
                urls.push(
                    ...Array.from(document.images).map(img => img.currentSrc || img.src || img.getAttribute('src')).filter(Boolean)
                );
                // 2) 样式表中的 url(...)
                urls.push(...extractUrlsFromStyles());
                // 3) appContent 字符串里可能的 <img src>
                try {
                    Object.values(appContent).forEach(v => {
                        if (!v) return;
                        if (typeof v === 'object') {
                            if (v.content) urls.push(...extractImgUrlsFromHtmlString(v.content));
                            // 对话框的 face/chest/crotch
                            if (v.face) urls.push(...extractImgUrlsFromHtmlString(v.face));
                            if (v.chest) urls.push(...extractImgUrlsFromHtmlString(v.chest));
                            if (v.crotch) urls.push(...extractImgUrlsFromHtmlString(v.crotch));
                            // 三段反应数组
                            if (Array.isArray(v.faceVariants)) v.faceVariants.forEach(s => urls.push(...extractImgUrlsFromHtmlString(s)));
                            if (Array.isArray(v.chestVariants)) v.chestVariants.forEach(s => urls.push(...extractImgUrlsFromHtmlString(s)));
                            if (Array.isArray(v.crotchVariants)) v.crotchVariants.forEach(s => urls.push(...extractImgUrlsFromHtmlString(s)));
                        }
                    });
                } catch (_) { /* 忽略 */ }
                // 4) 传入模板中的 <img src>
                urls.push(...extractImgUrlsFromHtmlString(TEMPLATE_INCOMING));
                // 去重与清洗
                return Array.from(new Set(urls.filter(Boolean)));
            };

            const urls = collectAllImageUrls();
            let loaded = 0;
            const total = urls.length;

            const update = () => {
                const progress = total === 0 ? 100 : Math.round((loaded / total) * 100);
                if (bar) bar.style.width = progress + '%';
                if (percentText) percentText.textContent = progress + '%';
            };
            update();

            const onOneDone = () => {
                loaded += 1;
                update();
                if (loaded >= total) {
                    // 小延迟更顺滑
                    setTimeout(() => {
                        preloader.classList.add('hidden');
                        // 等过渡完成再彻底移除节点，避免遮挡
                        setTimeout(() => {
                            preloader.remove();
                            initAfterPreload();
                        }, 450);
                    }, 120);
                }
            };

            if (total === 0) {
                // 无需预加载
                preloader.classList.add('hidden');
                setTimeout(() => { preloader.remove(); initAfterPreload(); }, 150);
                return;
            }

            urls.forEach((url) => {
                const img = new Image();
                img.onload = onOneDone;
                img.onerror = onOneDone; // 出错也计入，避免卡死
                img.src = url;
            });
        })();
    </script>
</body>
</html>
